// Aceita URL completa do ML ou o id cru. O id aparece na URL em duas
// formas: /MLB-123456789-titulo (com hifen) e /p/MLB123456789.

const f = $input.first().json;

const bruto = String(f['Link ou ID do produto'] || '').trim();
const urlAfiliado = String(f['Link de afiliado'] || '').trim();
const categoria = f['Categoria'] ? String(f['Categoria']).trim() : null;

if (!urlAfiliado.startsWith('http')) {
  throw new Error('O link de afiliado precisa comecar com http. Veio: ' + urlAfiliado);
}

let id = null;

const direto = bruto.match(/^(MLB\d+)$/i);
const comHifen = bruto.match(/MLB-(\d+)/i);
const semHifen = bruto.match(/MLB(\d{6,})/i);

if (direto) id = direto[1].toUpperCase();
else if (comHifen) id = 'MLB' + comHifen[1];
else if (semHifen) id = 'MLB' + semHifen[1];

if (!id) {
  throw new Error(
    'Nao achei um ID MLB em: ' +
      bruto +
      '. Cole a URL do anuncio ou o ID (ex: MLB123456789).'
  );
}

return [{ json: { produto_id: id, url_afiliado: urlAfiliado, categoria } }];

// Entrada manual fura a fila: score 100 e status APROVADO, entao o
// ORDER BY score DESC do publicador pega essa linha primeiro e,
// por ja vir APROVADO, nao passa de novo pela previa de aprovacao.

function esc(v) {
  if (v === null || v === undefined) return 'NULL';
  if (typeof v === 'number') return Number.isFinite(v) ? String(v) : 'NULL';
  const s = String(v)
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "\\'")
    .replace(/\u0000/g, '')
    .replace(/[\r\n]+/g, ' ')
    .trim();
  return "'" + s + "'";
}

const entrada = $('Extrair ID').first().json;
const item = $('Buscar Item').first().json;
const catRow = $('Resolver Categoria').first().json;
const categoriaId = catRow && catRow.id ? Number(catRow.id) : null;

if (!item || !item.id) {
  throw new Error('A API do ML nao devolveu o item ' + entrada.produto_id);
}

const preco = Number(item.price);
if (!Number.isFinite(preco) || preco <= 0) {
  throw new Error('Preco invalido no item ' + item.id);
}

const orig = Number(item.original_price);
const precoOriginal = Number.isFinite(orig) && orig > preco ? orig : null;
const desconto = precoOriginal
  ? Math.round((1 - preco / precoOriginal) * 100)
  : null;

let imagem = null;
if (Array.isArray(item.pictures) && item.pictures.length) {
  imagem = String(item.pictures[0].secure_url || item.pictures[0].url || '').replace(
    'http://',
    'https://'
  );
}
if (!imagem && item.thumbnail) {
  imagem = String(item.thumbnail)
    .replace('http://', 'https://')
    .replace(/-I\.jpg$/, '-O.jpg');
}
if (!imagem) throw new Error('Item sem imagem utilizavel: ' + item.id);

const detalhe = { manual: true, total: 100 };

const sqlLink =
  'INSERT INTO links_afiliados (produto_id, url_afiliado, observacao)\n' +
  'VALUES (' +
  esc(item.id) +
  ', ' +
  esc(entrada.url_afiliado) +
  ", 'cadastro manual via workflow C')\n" +
  'ON DUPLICATE KEY UPDATE url_afiliado = VALUES(url_afiliado)';

const sqlOferta =
  'INSERT INTO ofertas\n' +
  '  (produto_id, titulo, categoria_id, preco_atual, preco_original, desconto,\n' +
  '   frete_gratis, condicao, catalogo, vendidos, avaliacao, link_produto,\n' +
  '   imagem, score, score_detalhe, status)\n' +
  'VALUES (' +
  [
    esc(item.id),
    esc(String(item.title || '').slice(0, 250)),
    esc(categoriaId),
    preco.toFixed(2),
    precoOriginal == null ? 'NULL' : precoOriginal.toFixed(2),
    esc(desconto),
    item.shipping && item.shipping.free_shipping ? '1' : '0',
    esc(item.condition || null),
    item.catalog_listing || item.catalog_product_id ? '1' : '0',
    typeof item.sold_quantity === 'number' ? String(item.sold_quantity) : 'NULL',
    'NULL',
    esc(String(item.permalink || '').slice(0, 490)),
    esc(imagem.slice(0, 490)),
    '100',
    esc(JSON.stringify(detalhe)),
    "'APROVADO'",
  ].join(', ') +
  ')\n' +
  'ON DUPLICATE KEY UPDATE\n' +
  "  status = 'APROVADO',\n" +
  '  score = 100,\n' +
  '  tentativas = 0,\n' +
  '  proxima_tentativa = NULL,\n' +
  '  motivo = NULL,\n' +
  '  lock_owner = NULL';

return [
  {
    json: {
      produto_id: item.id,
      titulo: item.title,
      preco: preco,
      desconto,
      sqlLink,
      sqlOferta,
    },
  },
];

